class Solution:
    def isToeplitzMatrix(self, matrix: list[list[int]]) -> bool:
        diagonals = {}
        for row, values in enumerate(matrix):
            for column, value in enumerate(values):
                key = row - column
                if key in diagonals and diagonals[key] != value:
                    return False
                diagonals[key] = value
        return True
